pub async fn process_rpc_custody_columns(
    self: &Arc<Self>,
    custody_columns: DataColumnSidecarList<T::EthSpec>,
) -> Result<AvailabilityProcessingStatus, BlockError> {
    let Ok((slot, block_root)) = custody_columns
        .iter()
        .map(|c| (c.slot(), c.block_root()))
        .unique()
        .exactly_one()
    else {
        return Err(BlockError::InternalError(
            "Columns should be from the same block".to_string(),
        ));
    };

    // If this block has already been imported to forkchoice it must have been available, so
    // we don't need to process its columns again.
    if self
        .canonical_head
        .fork_choice_read_lock()
        .contains_block(&block_root)
    {
        return Err(BlockError::DuplicateFullyImported(block_root));
    }

    // Reject RPC columns referencing unknown parents. Otherwise we allow potentially invalid data
    // into the da_checker, where invalid = descendant of invalid blocks.
    // Note: custody_columns should have at least one item and all items have the same parent root.
    if let Some(parent_root) = custody_columns.iter().map(|c| c.block_parent_root()).next()
        && !self
            .canonical_head
            .fork_choice_read_lock()
            .contains_block(&parent_root)
    {
        return Err(BlockError::ParentUnknown { parent_root });
    }

    self.emit_sse_data_column_sidecar_events(
        &block_root,
        custody_columns.iter().map(|column| column.as_ref()),
    );

    let r = self
        .check_rpc_custody_columns_availability_and_import(slot, block_root, custody_columns)
        .await;
    self.remove_notified(&block_root, r)
}

pub async fn reconstruct_data_columns(
    self: &Arc<Self>,
    block_root: Hash256,
) -> Result<
    Option<(
        AvailabilityProcessingStatus,
        DataColumnSidecarList<T::EthSpec>,
    )>,
    BlockError,
> {
    // As of now we only reconstruct data columns on supernodes, so if the block is already
    // available on a supernode, there's no need to reconstruct as the node must already have
    // all columns.
    if self
        .canonical_head
        .fork_choice_read_lock()
        .contains_block(&block_root)
    {
        return Ok(None);
    }

    let data_availability_checker = self.data_availability_checker.clone();

    let result = self
        .task_executor
        .spawn_blocking_handle(
            move || data_availability_checker.reconstruct_data_columns(&block_root),
            "reconstruct_data_columns",
        )
        .ok_or(BeaconChainError::RuntimeShutdown)?
        .await
        .map_err(BeaconChainError::TokioJoin)??;

async fn check_rpc_custody_columns_availability_and_import(
    self: &Arc<Self>,
    slot: Slot,
    block_root: Hash256,
    custody_columns: DataColumnSidecarList<T::EthSpec>,
) -> Result<AvailabilityProcessingStatus, BlockError> {
    self.check_columns_for_slashability(
        block_root,
        custody_columns.iter().map(|c| c.as_ref()),
    )?;

    // This slot value is purely informative for the consumers of
    // `AvailabilityProcessingStatus::MissingComponents` to log an error with a slot.
    let availability = self.data_availability_checker.put_rpc_custody_columns(
        block_root,
        slot,
        custody_columns,
    )?;

    self.process_availability(slot, availability, || Ok(()))
        .await
}

fn check_columns_for_slashability<'a>(
    self: &Arc<Self>,
    block_root: Hash256,
    custody_columns: impl IntoIterator<Item = &'a DataColumnSidecar<T::EthSpec>>,
) -> Result<(), BlockError> {
    let mut slashable_cache = self.observed_slashable.write();
    // Process all unique block headers - previous logic assumed all headers were identical and
    // only processed the first one. However, we should not make assumptions about data received
    // from RPC.
    for header in custody_columns
        .into_iter()
        .map(|c| c.signed_block_header.clone())
        .unique()
    {
        if verify_header_signature::<T, BlockError>(self, &header).is_ok() {
            slashable_cache
                .observe_slashable(
                    header.message.slot,
                    header.message.proposer_index,
                    block_root,
                )
                .map_err(|e| BlockError::BeaconChainError(Box::new(e.into())))?;
            if let Some(slasher) = self.slasher.as_ref() {
                slasher.accept_block_header(header);
            }
        }
    }
    Ok(())
}

/// Imports a fully available block. Otherwise, returns `AvailabilityProcessingStatus::MissingComponents`
///
/// An error is returned if the block was unable to be imported. It may be partially imported
/// (i.e., this function is not atomic).
async fn process_availability(
    self: &Arc<Self>,
    slot: Slot,
    availability: Availability<T::EthSpec>,
    publish_fn: impl FnOnce() -> Result<(), BlockError>,
) -> Result<AvailabilityProcessingStatus, BlockError> {
    match availability {
        Availability::Available(block) => {
            publish_fn()?;
            // Block is fully available, import into fork choice
            self.import_available_block(block).await
        }
        Availability::MissingComponents(block_root) => Ok(
            AvailabilityProcessingStatus::MissingComponents(slot, block_root),
        ),
    }
}

#[instrument(skip_all)]
pub async fn import_available_block(
    self: &Arc<Self>,
    block: Box<AvailableExecutedBlock<T::EthSpec>>,
) -> Result<AvailabilityProcessingStatus, BlockError> {
    let AvailableExecutedBlock {
        block,
        import_data,
        payload_verification_outcome,
    } = *block;

    let BlockImportData {
        block_root,
        state,
        parent_block,
        consensus_context,
    } = import_data;

    // Record the time at which this block's blobs became available.
    if let Some(blobs_available) = block.blobs_available_timestamp() {
        self.block_times_cache.write().set_time_blob_observed(
            block_root,
            block.slot(),
            blobs_available,
        );

pub fn put_rpc_custody_columns(
    &self,
    block_root: Hash256,
    slot: Slot,
    custody_columns: DataColumnSidecarList<T::EthSpec>,
) -> Result<Availability<T::EthSpec>, AvailabilityCheckError> {
    // Attributes fault to the specific peer that sent an invalid column
    let kzg_verified_columns =
        KzgVerifiedDataColumn::from_batch_with_scoring(custody_columns, &self.kzg)
            .map_err(AvailabilityCheckError::InvalidColumn)?;

    // Filter out columns that aren't required for custody for this slot
    // This is required because `data_columns_by_root` requests the **latest** CGC that _may_
    // not be yet effective for data availability check, as CGC changes are only effecive from
    // a new epoch.
    let epoch = slot.epoch(T::EthSpec::slots_per_epoch());
    let sampling_columns = self
        .custody_context
        .sampling_columns_for_epoch(epoch, &self.spec);
    let verified_custody_columns = kzg_verified_columns
        .into_iter()
        .filter(|col| sampling_columns.contains(&col.index()))
        .map(KzgVerifiedCustodyDataColumn::from_asserted_custody)
        .collect::<Vec<_>>();

    self.availability_cache
        .put_kzg_verified_data_columns(block_root, verified_custody_columns)
}

/// Check if we've cached other blobs for this block. If it completes a set and we also
/// have a block cached, return the `Availability` variant triggering block import.
/// Otherwise cache the blob sidecar.
///
/// This should only accept gossip verified blobs, so we should not have to worry about dupes.
#[instrument(skip_all, level = "trace")]
pub fn put_gossip_verified_blobs<
    I: IntoIterator<Item = GossipVerifiedBlob<T, O>>,
    O: ObservationStrategy,
>(
    &self,
    block_root: Hash256,
    blobs: I,
) -> Result<Availability<T::EthSpec>, AvailabilityCheckError> {
    self.availability_cache
        .put_kzg_verified_blobs(block_root, blobs.into_iter().map(|b| b.into_inner()))
}

#[instrument(skip_all, level = "trace")]
pub fn put_kzg_verified_blobs<I: IntoIterator<Item = KzgVerifiedBlob<T::EthSpec>>>(
    &self,
    block_root: Hash256,
    blobs: I,
) -> Result<Availability<T::EthSpec>, AvailabilityCheckError> {
    self.availability_cache
        .put_kzg_verified_blobs(block_root, blobs)
}

/// Check if we've cached other data columns for this block. If it satisfies the custody requirement and we also
/// have a block cached, return the `Availability` variant triggering block import.
/// Otherwise cache the data column sidecar.
///
/// This should only accept gossip verified data columns, so we should not have to worry about dupes.
#[instrument(skip_all, level = "trace")]
pub fn put_gossip_verified_data_columns<
    O: ObservationStrategy,
    I: IntoIterator<Item = GossipVerifiedDataColumn<T, O>>,
>(
    &self,
    block_root: Hash256,
    slot: Slot,
    data_columns: I,
) -> Result<Availability<T::EthSpec>, AvailabilityCheckError> {
    let epoch = slot.epoch(T::EthSpec::slots_per_epoch());
    let sampling_columns = self
        .custody_context
        .sampling_columns_for_epoch(epoch, &self.spec);
    let custody_columns = data_columns
        .into_iter()
        .filter(|col| sampling_columns.contains(&col.index()))
        .map(|c| KzgVerifiedCustodyDataColumn::from_asserted_custody(c.into_inner()))
        .collect::<Vec<_>>();

    self.availability_cache
        .put_kzg_verified_data_columns(block_root, custody_columns)
}

#[instrument(skip_all, level = "trace")]
pub fn put_kzg_verified_custody_data_columns<
    I: IntoIterator<Item = KzgVerifiedCustodyDataColumn<T::EthSpec>>,
>(
    &self,
    block_root: Hash256,
    custody_columns: I,
) -> Result<Availability<T::EthSpec>, AvailabilityCheckError> {
    self.availability_cache
        .put_kzg_verified_data_columns(block_root, custody_columns)
}

